    supportPage: { title: "Supporto | Remotiq", description: "Supporto Remotiq per download, configurazione, abbinamento, rete locale, permessi e problemi comuni.", eyebrow: "Supporto Remotiq", heading: "Aiuto per configurazione e connessione", intro: "Remotiq funziona tra telefono e computer sulla stessa rete locale. Questi passaggi coprono download, abbinamento e permessi.", downloadLinks: "Link per il download", desktopDownload: "Scarica per Mac / Windows", allDownloads: "Tutte le opzioni", appAvailability: "L'app iPhone è sull'App Store. Il link Android sarà aggiunto dopo la pubblicazione.", firstSetup: "Prima configurazione", firstSteps: ["Installa Remotiq Desktop sul computer.", "Connetti entrambi i dispositivi allo stesso Wi-Fi.", "Apri Remotiq e tocca Connetti al computer.", "Scansiona il QR dell'app desktop.", "Usa il telefono come telecomando."], notFound: "Computer non trovato", notFoundItems: ["Verifica che i dispositivi usino lo stesso Wi-Fi.", "Disattiva temporaneamente la VPN.", "Consenti Remotiq sulle reti private nel Firewall di Windows.", "Abilita Rete locale su iPhone.", "Se la ricerca fallisce, usa QR o abbinamento manuale."], macPermissions: "Permessi macOS", macBody: "Il controllo di mouse e tastiera su Mac richiede il permesso Accessibilità. Usa il pulsante in Remotiq Desktop e riavvia l'app se necessario.", windowsNotes: "Note per Windows", windowsBody: "Windows può chiedere accesso al firewall al primo avvio. Consenti reti private/locali. Alcune app elevate o protette possono rifiutare input remoti.", security: "Sicurezza e privacy", securityBody: "I comandi restano nella rete locale e richiedono un dispositivo abbinato. Remotiq non usa account o relay internet; i report Firebase facoltativi si possono disattivare." },
    privacyPage: { title: "Informativa sulla privacy | Remotiq", description: "Privacy Remotiq: controllo locale, report Firebase facoltativi, annunci, permessi e scelte dell'utente.", eyebrow: "Informativa sulla privacy", heading: "Il controllo locale resta a te; la misurazione è una tua scelta.", intro: "Remotiq controlla il computer sulla rete locale. Non usa account o relay internet per i comandi. I report facoltativi Firebase su utilizzo, arresti e prestazioni possono essere disattivati.", updated: "Ultimo aggiornamento", summaryTitle: "Riepilogo", summaryItems: ["I comandi restano tra telefono e computer abbinato sulla rete locale.", "Remotiq non ha account né relay internet per i comandi.", "Firebase genera report pseudonimi su utilizzo, paese, sessioni, arresti e prestazioni.", "Si disattiva in Impostazioni > Privacy e diagnostica.", "Le versioni con annunci possono usare Google Mobile Ads.", "Dati del computer e chiave sicura restano sul dispositivo.", "La fotocamera serve solo all'abbinamento QR."], dataTitle: "Dati trattati", dataParagraphs: ["Remotiq mobile 1.0.3 build 20 e successivi usa Firebase Analytics, Crashlytics e Performance Monitoring. Possono trattare identificatore pseudonimo, prime aperture, sessioni e durata, schermate, metodo e successo di connessione, versione, lingua, dispositivo e sistema, paese/regione approssimativo derivato da Google, arresti e prestazioni. Remotiq non associa a Firebase nome, e-mail, telefono o account.", "Per abbinamento, riconnessione e prova senza annunci, l'app salva solo sul dispositivo nome computer, host/porta, piattaforma, ultima connessione, identificatore, token sicuro, preferenze e scadenza senza annunci.", "Indirizzi e IP/porta, codici, identificatori e token, testo digitato, URL, nomi app, documenti e screenshot non sono aggiunti a eventi o campi Crashlytics. Firebase Performance può trattare l'IP verso Google per segmentazione geografica approssimativa."], permissionsTitle: "Permessi", permissions: [["Fotocamera", "Solo per scansionare il QR di abbinamento."], ["Rete locale / Bonjour", "Per trovare e collegare Remotiq Desktop sullo stesso Wi-Fi."], ["Internet / Rete", "Per connessione locale, aggiornamenti, Firebase facoltativo e Google Mobile Ads nelle versioni con annunci."]], sharingTitle: "Condivisione e annunci", sharingParagraphs: ["Comandi e segreti non sono inviati ai server Remotiq. Google Firebase può trattare i dati limitati descritti per analisi, diagnostica e prestazioni. Google Mobile Ads può trattare dati di dispositivo, app e interazioni secondo criteri e permessi.", "Google User Messaging Platform verifica la scelta privacy prima degli annunci e mostra il consenso quando necessario. Su iOS il tracciamento personalizzato richiede App Tracking Transparency. Rifiutare non blocca le funzioni principali. Privacy annunci e Firebase sono scelte separate; disattivare le analisi ferma Analytics, Crashlytics e Performance Monitoring."], diagnosticsTitle: "Diagnostica e supporto", diagnosticsParagraphs: ["Puoi copiare volontariamente un riepilogo con connessione, versione, piattaforma, nome salvato ed errori. Token e hash sono esclusi.", "Con misurazione attiva, Crashlytics può trattare tracce di arresto, errori ripuliti, stato pertinente, dispositivo e sistema. Remotiq non aggiunge identità o segreti ai campi personalizzati."], deletionTitle: "Eliminazione dei dati", deletionBody: "Dimenticare un computer rimuove dati e token sicuro dal telefono. I dispositivi attendibili si possono rimuovere dal desktop. Disattivare Firebase reimposta i dati Analytics locali e ferma la raccolta futura. Disinstallare rimuove i dati locali. Senza identità account in Firebase, i report non sono ricercabili per nome o account.", childrenTitle: "Privacy dei minori", childrenBody: "Remotiq non è rivolto ai minori. Non richiede dati account direttamente identificativi; la misurazione è pseudonima.", contactTitle: "Contatti", contactBody: "Per privacy o supporto usa la pagina Remotiq:", contactLink: "Supporto Remotiq" },
    getPage: { title: "Scarica Remotiq Desktop", description: "Scarica Remotiq Desktop per Windows o macOS.", eyebrow: "Installazione computer", heading: "Installa Remotiq Desktop sul computer", lead: "Scegli Windows o Mac. Dopo l'installazione apri Remotiq sul computer.", mobileTitle: "Invia questo link al computer", mobileBody: "Apri questa pagina sul computer con AirDrop, Messaggi, e-mail o un'altra app.", share: "Condividi", copy: "Copia link", copied: "Link copiato.", macTitle: "Remotiq per Mac", macDesc: "Installer DMG per Mac Apple Silicon.", macButton: "Scarica per Mac", winTitle: "Remotiq per Windows", winDesc: "Installer consigliato per la maggior parte degli utenti.", winButton: "Scarica per Windows", msi: "Opzione MSI", installSteps: [["Installa:", "Apri il file scaricato sul computer."], ["Esegui:", "Lascia aperto Remotiq Desktop."], ["Connetti:", "Scansiona il QR con Remotiq sul telefono."]], safety: "Telefono e computer devono usare lo stesso Wi-Fi. Remotiq si collega direttamente sulla rete locale, non tramite cloud.", detectedMac: "macOS rilevato", detectedWindows: "Windows rilevato", mobileLead: "Sei su un telefono. Invia la pagina al computer per evidenziare il download corretto.", shareText: "Scarica l'app Remotiq per computer." },
