function fromEnglish(overrides) {
  return {
    ...structuredClone(locales.en),
    ...overrides,
    common: { ...locales.en.common, ...overrides.common },
    home: { ...locales.en.home, ...overrides.home },
    supportPage: { ...locales.en.supportPage, ...overrides.supportPage },
    privacyPage: { ...locales.en.privacyPage, ...overrides.privacyPage },
    getPage: { ...locales.en.getPage, ...overrides.getPage },
  };
}

