  supportPage: { title: "Dukungan | Remotiq", description: "Dukungan Remotiq untuk unduhan, penyiapan, pemasangan, jaringan lokal, dan izin.", eyebrow: "Dukungan Remotiq", heading: "Bantuan penyiapan dan sambungan", intro: "Remotiq bekerja antara ponsel dan komputer Anda pada jaringan lokal yang sama.", downloadLinks: "Tautan unduhan", desktopDownload: "Unduh untuk Mac / Windows", allDownloads: "Semua unduhan", appAvailability: "Aplikasi iPhone tersedia di App Store. Tautan Android ditambahkan setelah rilis.", firstSetup: "Penyiapan pertama", firstSteps: ["Instal Remotiq Desktop di komputer.", "Hubungkan kedua perangkat ke Wi-Fi yang sama.", "Buka Remotiq dan ketuk Hubungkan ke Komputer.", "Pindai QR aplikasi desktop.", "Gunakan ponsel sebagai remote."], notFound: "Komputer tidak ditemukan", notFoundItems: ["Pastikan kedua perangkat memakai Wi-Fi yang sama.", "Matikan VPN sementara.", "Izinkan Remotiq di jaringan privat Windows Firewall.", "Aktifkan izin Jaringan Lokal di iPhone.", "Gunakan QR atau pemasangan manual jika penemuan gagal."], macPermissions: "Izin macOS", macBody: "Kontrol mouse dan keyboard di Mac memerlukan izin Aksesibilitas. Gunakan tombol izin di Remotiq Desktop dan mulai ulang bila perlu.", windowsNotes: "Catatan Windows", windowsBody: "Windows mungkin meminta izin firewall. Izinkan jaringan privat/lokal. Beberapa aplikasi terlindungi dapat menolak input jarak jauh.", security: "Keamanan dan privasi", securityBody: "Perintah tetap di jaringan lokal dan memerlukan perangkat tepercaya. Tidak ada akun atau relay perintah; pelaporan Firebase opsional dapat dimatikan." },
  privacyPage: { title: "Kebijakan Privasi | Remotiq", description: "Privasi Remotiq: kontrol lokal, laporan Firebase opsional, iklan, izin, dan pilihan pengguna.", eyebrow: "Kebijakan Privasi", heading: "Kontrol lokal tetap milik Anda; pengukuran adalah pilihan Anda.", intro: "Remotiq bekerja di jaringan lokal tanpa akun atau relay internet untuk perintah. Laporan penggunaan, crash, dan performa Firebase dapat dimatikan.", updated: "Terakhir diperbarui", summaryTitle: "Ringkasan", summaryItems: ["Perintah tetap antara ponsel dan komputer yang dipasangkan di jaringan lokal.", "Remotiq tidak memiliki akun atau relay internet untuk perintah.", "Firebase digunakan untuk laporan penggunaan samaran, negara, sesi, crash, dan performa.", "Dapat dimatikan di Pengaturan > Privasi & diagnostik.", "Versi beriklan dapat menggunakan Google Mobile Ads.", "Detail komputer dan kunci aman disimpan di perangkat.", "Kamera hanya digunakan untuk pemasangan QR."], dataTitle: "Data yang Diproses", dataParagraphs: ["Remotiq mobile 1.0.3 build 20 dan yang lebih baru memakai Firebase Analytics, Crashlytics, dan Performance Monitoring. Layanan ini dapat memproses ID instans samaran, pembukaan pertama, sesi dan durasi, layar, metode dan hasil sambungan, versi, bahasa, perangkat dan OS, negara/wilayah perkiraan dari Google, crash, serta performa. Remotiq tidak menetapkan nama, email, telepon, atau ID akun ke Firebase.", "Untuk pemasangan dan sambungan ulang, nama komputer, host/port, platform, sambungan terakhir, ID perangkat, token aman, dan preferensi hanya disimpan di perangkat.", "Alamat dan IP/port komputer, kode, ID dan token, teks, URL, nama aplikasi, dokumen, dan tangkapan layar tidak ditambahkan ke peristiwa atau bidang crash Firebase."], permissionsTitle: "Izin", permissions: [["Kamera", "Hanya untuk memindai QR pemasangan Remotiq."], ["Jaringan Lokal / Bonjour", "Untuk menemukan dan terhubung ke Remotiq Desktop di Wi-Fi yang sama."], ["Internet / Jaringan", "Untuk sambungan lokal, pemeriksaan pembaruan, Firebase opsional, dan Google Mobile Ads pada versi beriklan."]], sharingTitle: "Berbagi dan Iklan", sharingParagraphs: ["Perintah dan rahasia pemasangan tidak dikirim ke server Remotiq. Google Firebase dapat memproses data terbatas tersebut untuk analitik, diagnostik, dan performa.", "Google User Messaging Platform memeriksa pilihan privasi sebelum iklan. Di iOS, pelacakan personal memerlukan App Tracking Transparency; penolakan tidak memblokir fitur inti."], diagnosticsTitle: "Diagnostik dan Dukungan", diagnosticsParagraphs: ["Anda dapat menyalin ringkasan diagnostik berisi status, versi, platform, nama komputer, dan kode kesalahan. Token dikecualikan.", "Saat pengukuran aktif, Crashlytics dapat memproses jejak crash, kesalahan yang disunting, perangkat, dan OS tanpa identitas pengguna atau rahasia sambungan."], deletionTitle: "Menghapus Data", deletionBody: "Melupakan komputer menghapus detail dan token aman dari ponsel. Menonaktifkan Firebase mereset data Analytics di perangkat dan menghentikan pengumpulan berikutnya. Menghapus aplikasi menghapus data lokal.", childrenTitle: "Privasi Anak", childrenBody: "Remotiq tidak ditujukan untuk anak-anak dan tidak meminta data akun yang langsung mengidentifikasi.", contactTitle: "Kontak", contactBody: "Untuk pertanyaan privasi atau dukungan, gunakan halaman berikut:", contactLink: "Dukungan Remotiq" },
